// Banco de questoes - Lingua Portuguesa (2as avaliacoes do 3o trimestre) - 5o ano - prova 16/11
window.BANCO = window.BANCO || {};
window.BANCO.portugues = [
{n:"f",t:"Interpretação de texto",q:"Leia:\nLia acordou cedo no sábado. Pegou a bicicleta, encheu a garrafa de água e pedalou até o parque. Lá, encontrou os amigos para um piquenique.\nPara onde Lia foi de bicicleta?",a:["À escola","Ao parque","À praia","À casa da avó"],c:1,e:"O texto diz que Lia 'pedalou até o parque'. A resposta está escrita no próprio texto: é só procurar com atenção! 🚲"},
{n:"f",t:"Interpretação de texto",q:"Leia:\nO cachorro Tobias late sempre que o carteiro chega. A família já sabe: quando Tobias faz barulho às dez horas, é sinal de que chegaram cartas.\nQual é o sinal de que chegaram cartas?",a:["O toque da campainha","O carteiro gritar o nome da família","O latido de Tobias às dez horas","A caixa de correio cair"],c:2,e:"O texto conta que, quando Tobias late às dez horas, é sinal de que o carteiro trouxe cartas. 🐶✉️"},
{n:"f",t:"Interpretação de texto",q:"Leia:\nDepois da longa caminhada pela trilha, os meninos estavam exaustos e dormiram logo.\nNo texto, a palavra 'exaustos' significa...",a:["muito felizes","com muita fome","muito assustados","muito cansados"],c:3,e:"Quem faz uma longa caminhada fica muito cansado. Por isso os meninos dormiram logo: estavam exaustos!"},
{n:"f",t:"Interpretação de texto",q:"Leia:\nChoveu a tarde inteira. Quando o sol voltou, Pedro correu para o quintal e viu um arco-íris enorme sobre as árvores.\nO que aconteceu ANTES de Pedro ver o arco-íris?",a:["Choveu a tarde inteira","Pedro foi dormir cedo","Pedro plantou várias árvores","Nevou forte no quintal"],c:0,e:"A primeira frase conta que choveu a tarde inteira. Só depois o sol voltou e Pedro viu o arco-íris. 🌈"},
{n:"f",t:"Interpretação de texto",q:"Leia:\nAs abelhas são muito importantes para a natureza. Ao voar de flor em flor, elas levam o pólen e ajudam as plantas a produzir frutos e sementes.\nQual é o assunto principal do texto?",a:["O mel que as abelhas fabricam na colmeia","Como as abelhas ajudam as plantas","O perigo das picadas de abelha","As cores das flores do jardim"],c:1,e:"O texto todo explica como as abelhas ajudam as plantas a dar frutos e sementes. O mel e as picadas nem aparecem no texto! 🐝"},
{n:"f",t:"Interpretação de texto",q:"Leia:\nATENÇÃO, ALUNOS! A feira de ciências será na sexta-feira, às 14h, no pátio. Tragam seus trabalhos prontos!\nPara que serve esse texto?",a:["Para contar uma longa história de aventura","Para ensinar uma receita de bolo","Para descrever o pátio da escola","Para avisar sobre a feira de ciências"],c:3,e:"É um aviso: informa o dia, a hora e o lugar da feira e lembra os alunos de levar os trabalhos. 📢"},
{n:"f",t:"Interpretação de texto",q:"Leia:\nAna olhou pela janela, viu o céu escuro, cheio de nuvens, e pegou o guarda-chuva antes de sair.\nPor que Ana pegou o guarda-chuva?",a:["Porque estava fazendo muito sol","Porque achou que ia chover","Porque ia emprestá-lo a uma amiga","Porque o guarda-chuva era novo"],c:1,e:"Céu escuro e cheio de nuvens é sinal de chuva. O texto não diz isso com todas as letras: a gente descobre pelas pistas! ☔"},
{n:"f",t:"Interpretação de texto",q:"Leia:\nMariana ficou radiante quando soube que tinha passado no teste de natação. Pulou, gritou e abraçou a mãe.\nNo texto, a palavra 'radiante' quer dizer...",a:["muito triste","com medo","muito alegre","com raiva"],c:2,e:"Mariana pulou, gritou e abraçou a mãe: tudo isso mostra muita alegria. Radiante é quem está brilhando de felicidade! ✨"},
{n:"f",t:"Gêneros textuais",q:"Como se chama cada linha de um poema?",a:["parágrafo","verso","capítulo","estrofe"],c:1,e:"Cada linha do poema é um verso. Um grupo de versos forma uma estrofe."},
{n:"f",t:"Gêneros textuais",q:"Em um poema, um conjunto de versos separado dos outros por um espaço é chamado de...",a:["rima","título","estrofe","parágrafo"],c:2,e:"A estrofe é um bloquinho de versos. Entre uma estrofe e outra, costuma haver um espaço em branco."},
{n:"f",t:"Gêneros textuais",q:"Quando duas palavras terminam com o mesmo som, como 'janela' e 'panela', dizemos que elas...",a:["são estrofes","são versos","são sinônimos","rimam"],c:3,e:"Rima é a repetição de sons no final das palavras: janela, panela, canela... Os poemas usam muito as rimas! 🎵"},
{n:"f",t:"Gêneros textuais",q:"Em um texto narrativo, quem conta a história?",a:["o narrador","o leitor","o ilustrador","o editor"],c:0,e:"O narrador é a 'voz' que conta a história. Ele pode participar dela ou apenas observar o que acontece."},
{n:"f",t:"Gêneros textuais",q:"Qual gênero textual conta a vida de uma pessoa real, com datas e fatos importantes?",a:["poema","fábula","biografia","receita"],c:2,e:"A biografia conta a história da vida de uma pessoa real: onde nasceu, o que fez e por que ficou conhecida."},
{n:"f",t:"Gêneros textuais",q:"Um texto que apresenta um livro ou filme e dá a opinião de quem escreveu, dizendo se vale a pena, é uma...",a:["biografia","resenha","receita","lista de compras"],c:1,e:"A resenha descreve uma obra (livro, filme, jogo...) e a avalia, muitas vezes recomendando ou não. 🎬📚"},
{n:"f",t:"Gêneros textuais",q:"Qual é o principal objetivo de um artigo de opinião?",a:["Contar a vida de uma pessoa","Ensinar a fazer um bolo","Rimar palavras bonitas","Defender um ponto de vista"],c:3,e:"No artigo de opinião, o autor defende uma ideia e usa argumentos para convencer o leitor."},
{n:"f",t:"Gêneros textuais",q:"A crônica geralmente fala sobre...",a:["fatos do dia a dia, com linguagem leve","a vida de uma pessoa famosa, com datas","instruções para montar um brinquedo","as regras de um jogo de tabuleiro"],c:0,e:"A crônica parte de situações do cotidiano (uma fila, um passeio, uma conversa) e conta tudo de um jeito leve, muitas vezes com humor."},
{n:"f",t:"Gêneros textuais",q:"Qual é a finalidade de um texto informativo?",a:["Fazer o leitor rir com uma piada","Informar e explicar um assunto","Contar um sonho inventado","Convencer a comprar um produto"],c:1,e:"O texto informativo traz informações e explicações sobre um assunto, como os textos de livros didáticos e enciclopédias."},
{n:"f",t:"Gêneros textuais",q:"Onde costumamos encontrar reportagens?",a:["Em livros de receitas","Em bulas de remédio","Em jornais e revistas","Em cartões de aniversário"],c:2,e:"Reportagens são publicadas em jornais, revistas, sites de notícias e também na TV. 📰"},
{n:"f",t:"Gêneros textuais",q:"Leia:\nO gato subiu no telhado,\nolhou a lua prateada,\nmiou baixinho, encantado,\ne dormiu de madrugada.\nEsse trecho pertence a qual gênero textual?",a:["reportagem","biografia","resenha","poema"],c:3,e:"O trecho está escrito em versos e tem rimas (telhado/encantado, prateada/madrugada). Essas são marcas do poema! 🐱🌙"},
{n:"f",t:"Gêneros textuais",q:"Leia:\nEra uma vez uma tartaruga chamada Lili que sonhava conhecer o mar. Um dia, ela arrumou a mochila e partiu em viagem.\nEsse trecho pertence a qual gênero textual?",a:["texto narrativo","artigo de opinião","texto informativo","biografia"],c:0,e:"'Era uma vez', uma personagem (Lili) e uma história acontecendo: são marcas do texto narrativo. 🐢"},
{n:"f",t:"Substantivo",q:"Na frase 'A professora Helena chegou cedo à escola.', qual palavra é um substantivo próprio?",a:["professora","Helena","escola","cedo"],c:1,e:"Helena é o nome específico de uma pessoa, por isso é substantivo próprio e começa com letra maiúscula. 'Professora' e 'escola' são comuns."},
{n:"f",t:"Substantivo",q:"Qual é o coletivo de abelhas?",a:["cardume","alcateia","enxame","rebanho"],c:2,e:"Um grupo de abelhas forma um enxame. 🐝 Cardume é de peixes, alcateia é de lobos e rebanho é de ovelhas ou gado."},
{n:"f",t:"Substantivo",q:"Qual destas palavras é um substantivo abstrato?",a:["mesa","cachorro","lápis","alegria"],c:3,e:"Alegria é um sentimento: não existe sozinha, depende de alguém para existir. Por isso é abstrato. Mesa, cachorro e lápis são concretos."},
{n:"f",t:"Substantivo",q:"Qual destas palavras é um substantivo concreto?",a:["bola","saudade","amizade","coragem"],c:0,e:"Bola é um ser que existe por si mesmo. Saudade, amizade e coragem são sentimentos ou qualidades, por isso são abstratos. ⚽"},
{n:"f",t:"Substantivo",q:"Qual é o plural de 'flor'?",a:["flors","flores","floris","florzes"],c:1,e:"Palavras terminadas em -r ganham -es no plural: flor → flores, como mar → mares. 🌸"},
{n:"f",t:"Substantivo",q:"Qual é o feminino de 'cavalo'?",a:["cavala","cavaleira","égua","cavalona"],c:2,e:"O feminino de cavalo é égua, uma palavra totalmente diferente! 🐴 Isso também acontece com boi → vaca e bode → cabra."},
{n:"f",t:"Substantivo",q:"Na frase 'A couve-flor estava na geladeira.', qual é o substantivo composto?",a:["geladeira","estava","flor","couve-flor"],c:3,e:"Couve-flor junta duas palavras (couve + flor) para formar um só nome. Por isso é composto. 🥦"},
{n:"f",t:"Aposto e vocativo",q:"O que é vocativo?",a:["Termo usado para chamar o ouvinte","Palavra que indica uma ação","Termo que explica outro termo","Palavra que dá uma qualidade ao nome"],c:0,e:"Vocativo é o termo que usamos para chamar ou falar diretamente com alguém, como em 'Pedro, venha cá!'."},
{n:"f",t:"Aposto e vocativo",q:"O que é aposto?",a:["Termo usado para chamar alguém","Termo que explica outro termo","Palavra que indica uma ação","Palavra que substitui o nome"],c:1,e:"O aposto explica ou especifica outro termo da frase, como em 'Brasília, a capital do Brasil, é linda'."},
{n:"f",t:"Aposto e vocativo",q:"Na frase 'Pedro, venha jantar!', a palavra 'Pedro' é...",a:["aposto","adjetivo","vocativo","verbo"],c:2,e:"Quem fala está chamando o Pedro. Termo usado para chamar alguém é vocativo, e vem separado por vírgula."},
{n:"f",t:"Aposto e vocativo",q:"Na frase 'Brasília, a capital do Brasil, foi inaugurada em 1960.', qual é o aposto?",a:["Brasília","foi inaugurada","em 1960","a capital do Brasil"],c:3,e:"'A capital do Brasil' explica o que é Brasília. Termo que explica outro, entre vírgulas, é aposto."},
{n:"f",t:"Aposto e vocativo",q:"Na frase 'Mãe, posso brincar lá fora?', qual é o vocativo?",a:["Mãe","posso","brincar","lá fora"],c:0,e:"A criança está chamando a mãe para fazer a pergunta. 'Mãe' é o vocativo."},
{n:"f",t:"Aposto e vocativo",q:"Qual sinal de pontuação costuma separar o vocativo do restante da frase?",a:["ponto final","hífen","vírgula","reticências"],c:2,e:"O vocativo vem separado por vírgula: 'Ana, venha cá!' ou 'Venha cá, Ana!'."},
{n:"f",t:"Aposto e vocativo",q:"Na frase 'Rex, o meu cachorro, adora correr na praia.', o termo 'o meu cachorro' é...",a:["vocativo","aposto","verbo","numeral"],c:1,e:"'O meu cachorro' explica quem é Rex. Por isso é aposto. Ninguém está chamando o Rex na frase! 🐕"},
{n:"f",t:"Adjetivo",q:"Na frase 'O gato preto dormiu no sofá.', qual palavra é adjetivo?",a:["gato","dormiu","preto","sofá"],c:2,e:"'Preto' diz como é o gato: é uma característica. Palavra que caracteriza o substantivo é adjetivo. 🐈"},
{n:"f",t:"Adjetivo",q:"Qual é a função do adjetivo?",a:["Indicar uma ação ou um acontecimento","Caracterizar o substantivo","Ligar duas palavras da frase","Substituir o nome de alguém"],c:1,e:"O adjetivo dá qualidade ou característica ao substantivo: casa grande, dia lindo, bolo gostoso."},
{n:"f",t:"Adjetivo",q:"Qual destas palavras é um adjetivo?",a:["correr","casa","depressa","bonito"],c:3,e:"'Bonito' indica uma qualidade (menino bonito, dia bonito). Correr é verbo, casa é substantivo e depressa indica o modo de fazer algo."},
{n:"f",t:"Adjetivo",q:"Na frase 'A menina simpática ajudou o colega.', a palavra 'simpática' indica...",a:["uma qualidade da menina","uma ação feita pela menina","o nome próprio da menina","o lugar da menina"],c:0,e:"'Simpática' mostra como a menina é: é uma qualidade, ou seja, um adjetivo. 😊"},
{n:"f",t:"Adjetivo",q:"Em 'brinquedo de criança', a expressão 'de criança' pode ser trocada pelo adjetivo...",a:["adulto","infantil","juvenil","criativo"],c:1,e:"'De criança' é uma locução adjetiva que equivale a 'infantil': brinquedo infantil. Juvenil é de jovem."},
{n:"f",t:"Artigo",q:"Quais são os artigos definidos?",a:["um, uma, uns, umas","o, a, os, as","eu, tu, ele, ela","de, em, por, com"],c:1,e:"Os artigos definidos são o, a, os, as. Eles indicam um ser certo, já conhecido: 'o livro que eu te mostrei'."},
{n:"f",t:"Artigo",q:"Quais são os artigos indefinidos?",a:["o, a, os, as","meu, minha, teu, tua","um, uma, uns, umas","este, esse, aquele"],c:2,e:"Os artigos indefinidos são um, uma, uns, umas. Eles indicam um ser qualquer, não específico: 'um livro'."},
{n:"f",t:"Artigo",q:"Na frase 'A menina ganhou uma boneca.', quais palavras são artigos?",a:["menina e boneca","ganhou e uma","A e menina","A e uma"],c:3,e:"'A' é artigo definido e 'uma' é artigo indefinido. Eles vêm antes dos substantivos menina e boneca."},
{n:"f",t:"Artigo",q:"Na frase 'Os alunos visitaram o museu.', o artigo 'Os' é...",a:["definido, masculino, plural","indefinido, masculino, plural","definido, feminino, singular","indefinido, feminino, plural"],c:0,e:"'Os' é artigo definido e concorda com 'alunos': masculino e plural."},
{n:"f",t:"Preposição",q:"Qual destas palavras é uma preposição?",a:["bonito","correr","com","mesa"],c:2,e:"'Com' é preposição: ela liga palavras, como em 'café com leite'. ☕"},
{n:"f",t:"Preposição",q:"Na frase 'O livro está sobre a mesa.', qual é a preposição?",a:["livro","está","mesa","sobre"],c:3,e:"'Sobre' liga 'livro' e 'mesa' e mostra a posição do livro: em cima da mesa."},
{n:"f",t:"Preposição",q:"Na frase 'Fui ao cinema com meu primo.', a preposição 'com' indica...",a:["companhia","lugar","tempo","finalidade"],c:0,e:"'Com meu primo' mostra quem estava junto: indica companhia. 🎬"},
{n:"f",t:"Preposição",q:"A palavra 'do', em 'a casa do vizinho', é a junção de...",a:["da + o","de + o","em + o","de + um"],c:1,e:"'Do' é a preposição 'de' junto com o artigo 'o': de + o = do."},
{n:"f",t:"Preposição",q:"Qual é a função da preposição?",a:["Indicar ações","Nomear seres","Ligar palavras","Qualificar seres"],c:2,e:"A preposição liga duas palavras e cria uma relação de sentido entre elas: 'suco de uva', 'bolo para a festa'."},
{n:"f",t:"Verbo",q:"Qual destas palavras é um verbo?",a:["corrida","rápido","pista","correr"],c:3,e:"'Correr' indica uma ação, por isso é verbo. 'Corrida' e 'pista' são substantivos e 'rápido' é adjetivo. 🏃"},
{n:"f",t:"Verbo",q:"Na frase 'Choveu muito ontem.', o verbo 'choveu' indica...",a:["um fenômeno da natureza","uma ação feita por uma pessoa","uma qualidade","um estado de espírito"],c:0,e:"Chover, ventar, trovejar e nevar são verbos que indicam fenômenos da natureza. 🌧️"},
{n:"f",t:"Verbo",q:"Na frase 'Ana está feliz.', o verbo 'está' indica...",a:["ação","estado","fenômeno da natureza","lugar"],c:1,e:"'Está' mostra como Ana se encontra (feliz). Verbos como ser, estar, ficar e parecer costumam indicar estado."},
{n:"f",t:"Verbo",q:"Na frase 'Amanhã nós viajaremos para a praia.', o verbo indica uma ação que...",a:["já aconteceu (pretérito)","está acontecendo agora (presente)","ainda vai acontecer (futuro)","acontece sempre (presente)"],c:2,e:"'Amanhã' e 'viajaremos' mostram algo que ainda vai acontecer: é o futuro. 🏖️"},
{n:"f",t:"Verbo",q:"Na frase 'Ontem eu brinquei no parque.', o verbo 'brinquei' está no...",a:["presente","pretérito (passado)","futuro do presente","modo imperativo afirmativo"],c:1,e:"'Ontem' e 'brinquei' mostram uma ação que já aconteceu: é o pretérito, ou seja, o passado."},
{n:"f",t:"Verbo",q:"Na frase 'Feche a porta, por favor.', o verbo 'feche' está no modo...",a:["indicativo","subjuntivo","imperativo","infinitivo"],c:2,e:"É um pedido! Quando damos ordens, fazemos pedidos ou damos conselhos, usamos o modo imperativo. 🚪"},
{n:"f",t:"Verbo",q:"O modo imperativo é usado para...",a:["expressar uma certeza sobre os fatos","expressar dúvida ou desejo","contar fatos que já passaram","dar ordens, pedidos ou conselhos"],c:3,e:"Imperativo é o modo da ordem, do pedido e do conselho: 'Estude!', 'Ajude-me, por favor', 'Durma cedo'."},
{n:"f",t:"Verbo",q:"O modo indicativo expressa, principalmente...",a:["certeza","dúvida","ordem","desejo"],c:0,e:"O indicativo fala de fatos com certeza: 'Eu estudo', 'Eu estudei', 'Eu estudarei'."},
{n:"f",t:"Verbo",q:"O modo subjuntivo expressa, principalmente...",a:["certeza sobre um fato real","ordem ou pedido direto","dúvida, desejo ou hipótese","fatos que foram comprovados"],c:2,e:"O subjuntivo aparece quando há dúvida, desejo ou hipótese: 'Talvez eu vá', 'Tomara que chova', 'Se eu pudesse...'."},
{n:"f",t:"Verbo",q:"Na frase 'Eu estudo todos os dias.', o verbo 'estudo' está no modo...",a:["subjuntivo","indicativo","imperativo","infinitivo"],c:1,e:"A frase afirma um fato com certeza: eu estudo todos os dias. Certeza = modo indicativo. 📚"},
{n:"f",t:"Pronome",q:"Quais são os pronomes pessoais do caso reto?",a:["me, te, se, lhe, nos, vos, lhes","eu, tu, ele, nós, vós, eles","meu, teu, seu, nosso","este, esse, aquele"],c:1,e:"Os pronomes pessoais do caso reto são: eu, tu, ele/ela, nós, vós, eles/elas."},
{n:"f",t:"Pronome",q:"Na frase 'Ela comprou pão na padaria.', a palavra 'Ela' é um pronome...",a:["pessoal do caso oblíquo","possessivo","pessoal do caso reto","demonstrativo"],c:2,e:"'Ela' é pronome pessoal do caso reto e está no lugar do nome de uma pessoa (3ª pessoa do singular)."},
{n:"f",t:"Pronome",q:"Qual destas palavras é um pronome possessivo?",a:["meu","eu","este","você"],c:0,e:"'Meu' indica posse, ou seja, que algo pertence a alguém: meu livro, minha casa."},
{n:"f",t:"Pronome",q:"Qual pronome de tratamento usamos para conversar com um amigo, de forma informal?",a:["Vossa Excelência","Vossa Majestade","você","Vossa Santidade"],c:2,e:"'Você' é o pronome de tratamento informal, usado com amigos e família. Os outros são para autoridades: presidente, rei e papa."},
{n:"f",t:"Pronome",q:"Para que serve o pronome?",a:["Para indicar uma ação","Para ligar duas palavras","Para indicar a quantidade exata dos seres","Para substituir ou acompanhar o nome"],c:3,e:"O pronome substitui ou acompanha o substantivo. Assim evitamos repetir palavras: 'Ana chegou. Ela estava feliz.'"},
{n:"f",t:"Pronome",q:"Na frase 'Este caderno é meu.', a palavra 'Este' é um pronome...",a:["demonstrativo","pessoal do caso reto","de tratamento","pessoal do caso oblíquo"],c:0,e:"'Este' mostra a posição do caderno em relação a quem fala (está perto). Pronome que 'aponta' é demonstrativo. 👉"},
{n:"f",t:"Numeral",q:"Qual destas palavras é um numeral ordinal?",a:["um","primeiro","dobro","metade"],c:1,e:"O ordinal indica ordem ou posição: primeiro, segundo, terceiro... 🥇"},
{n:"f",t:"Numeral",q:"Qual destas palavras é um numeral cardinal?",a:["quinto","quíntuplo","um quinto","cinco"],c:3,e:"O cardinal indica quantidade: um, dois, três, cinco... Quinto é ordinal, quíntuplo é multiplicativo e um quinto é fracionário."},
{n:"f",t:"Numeral",q:"A palavra 'dobro' é um numeral...",a:["cardinal","ordinal","multiplicativo","fracionário"],c:2,e:"Dobro quer dizer 'duas vezes mais'. Numerais que multiplicam (dobro, triplo, quádruplo) são multiplicativos. ✖️"},
{n:"f",t:"Numeral",q:"A palavra 'metade' é um numeral...",a:["fracionário","multiplicativo","ordinal","cardinal"],c:0,e:"Metade indica uma parte de um todo dividido em dois. Numerais que dividem (metade, terço, quarto) são fracionários. 🍕"},
{n:"f",t:"Numeral",q:"Como se lê 'século XXI'?",a:["século dezenove","século onze","século vinte e um","século vinte e dois"],c:2,e:"XXI = X + X + I = 21. A partir do século XI, lemos com o número cardinal: século vinte e um."},
{n:"f",t:"Numeral",q:"Na frase 'Gustavo chegou em terceiro lugar na corrida.', a palavra 'terceiro' é um numeral...",a:["cardinal","ordinal","multiplicativo","fracionário"],c:1,e:"'Terceiro' indica a posição de Gustavo na corrida, ou seja, a ordem. Por isso é ordinal. 🥉"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nJoaquim colocou mais uma moeda no cofrinho e sorriu. Faltavam só dez reais para comprar a bola nova. Naquele mês, ele tinha deixado de comprar balas na cantina.\nO que podemos concluir sobre Joaquim?",a:["Ele parou de gostar de balas na cantina","Ele está economizando para comprar a bola","Ele perdeu o cofrinho que tinha na escola","Ele já comprou a bola nova"],c:1,e:"Joaquim deixou de comprar balas e guardou moedas porque quer juntar dinheiro para a bola. O texto não diz que ele deixou de gostar de balas! 💰⚽"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nQuando o professor anunciou uma prova surpresa, a turma inteira ficou de cabelo em pé.\nA expressão 'ficar de cabelo em pé' significa...",a:["ficar assustado ou preocupado","pentear o cabelo para cima","ficar muito alegre e animado","levantar da cadeira depressa"],c:0,e:"É uma expressão de sentido figurado: ninguém arrepiou o cabelo de verdade! Quer dizer que a turma ficou assustada com a prova surpresa. 😱"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nOs moradores da Rua das Flores fizeram um mutirão no domingo. Uns pintaram o muro da praça, outros plantaram mudas e as crianças recolheram o lixo. No fim do dia, a praça parecia nova.\nQual é a ideia principal do texto?",a:["As crianças brincaram na praça no domingo","A prefeitura reformou a praça da rua","Os moradores se uniram para cuidar da praça","O muro da praça caiu no domingo"],c:2,e:"Todos trabalharam juntos (pintando, plantando e limpando) para deixar a praça bonita. Mutirão é justamente isso: um grupo que se une para fazer um trabalho. 🧹🌱"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nVovó passou a manhã procurando os óculos. Andou pela casa toda, olhou embaixo do sofá e até dentro da geladeira. Só parou quando se olhou no espelho e começou a rir.\nO que a vovó provavelmente descobriu ao se olhar no espelho?",a:["Que o espelho estava sujo","Que os óculos estavam no próprio rosto","Que tinha esquecido de pentear o cabelo","Que a geladeira estava aberta"],c:1,e:"Ela riu porque os óculos estavam no rosto dela o tempo todo! O texto não diz isso diretamente: descobrimos pelas pistas (o espelho e a risada). 👓😂"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nColoque um pouco de algodão molhado em um copo. Ponha três grãos de feijão em cima e deixe o copo perto da janela. Regue um pouquinho todos os dias e observe.\nQual é a finalidade desse texto?",a:["Contar uma aventura com feijões","Dar uma opinião sobre o feijão","Ensinar a fazer uma experiência","Noticiar um fato que aconteceu"],c:2,e:"O texto dá instruções, passo a passo, para fazer uma experiência. Repare nos verbos que orientam o leitor: coloque, ponha, regue, observe. 🌱"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nComo a ponte do rio Azul caiu durante a tempestade, os alunos da vila precisaram ir de barco até a escola durante uma semana.\nPor que os alunos foram de barco para a escola?",a:["Porque a ponte tinha caído","Porque gostavam de passear de barco","Porque a escola mudou de lugar","Porque a estrada estava em obras"],c:0,e:"A causa está no começo do texto: a ponte caiu na tempestade. A consequência foi ter que ir de barco. ⛵"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nO cientista ficou perplexo: a planta, que deveria murchar no escuro, tinha crescido ainda mais.\nNo texto, 'perplexo' significa...",a:["feliz e satisfeito","cansado e com muito sono","espantado, sem entender","bravo e irritado"],c:2,e:"O cientista esperava uma coisa e aconteceu outra! Por isso ficou perplexo, ou seja, espantado e sem entender. 🤔"},
{n:"m",t:"Interpretação de texto",q:"Leia:\nLucas olhou para o chão, apertou a mochila contra o peito e respondeu baixinho:\n— Eu... esqueci a lição.\nComo Lucas provavelmente estava se sentindo?",a:["orgulhoso","envergonhado","entusiasmado","furioso"],c:1,e:"Olhar para o chão, falar baixinho e hesitar ('Eu...') são pistas de que Lucas estava envergonhado. 😳"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nNaquela noite de inverno, na pequena cabana da floresta, os irmãos ouviram um barulho estranho.\nA expressão 'na pequena cabana da floresta' indica...",a:["o tempo da narrativa","o espaço da narrativa","o narrador da história","o clímax da história"],c:1,e:"O espaço é o lugar onde a história acontece: a cabana da floresta. Já 'naquela noite de inverno' indica o tempo. 🏡🌲"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nHá muitos anos, numa aldeia à beira do rio, vivia um pescador muito pobre.\nQual expressão indica o TEMPO da narrativa?",a:["numa aldeia","à beira do rio","Há muitos anos","um pescador muito pobre"],c:2,e:"'Há muitos anos' diz QUANDO a história aconteceu: é o tempo. 'Numa aldeia à beira do rio' diz ONDE: é o espaço."},
{n:"m",t:"Gêneros textuais",q:"Em uma narrativa, como se chama o momento de maior tensão, quando o conflito chega ao ponto mais emocionante?",a:["desfecho","clímax","situação inicial","apresentação"],c:1,e:"O clímax é o ponto alto da história, quando a emoção está no máximo. Depois dele vem o desfecho. 🎢"},
{n:"m",t:"Gêneros textuais",q:"O que é o desfecho de uma narrativa?",a:["o começo, quando os personagens surgem","o lugar onde a história se passa","o momento de maior suspense","o final, quando o conflito se resolve"],c:3,e:"O desfecho é o final da história, quando o problema (conflito) é resolvido, de um jeito feliz ou não."},
{n:"m",t:"Gêneros textuais",q:"Leia:\nEu nunca tinha visto um mar tão azul. Corri para a água sem pensar duas vezes.\nNesse trecho, o narrador...",a:["participa da história","só observa a história de fora","é o leitor do texto","não aparece no texto"],c:0,e:"O narrador usa 'eu' e 'corri': ele vive a história. É o narrador-personagem, que conta em 1ª pessoa. 🌊"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nO filme 'Viagem ao Planeta Doce' diverte do começo ao fim. As cores são lindas e as músicas são animadas. Recomendo para toda a família!\nEsse trecho pertence a qual gênero textual?",a:["biografia","poema","resenha","texto informativo"],c:2,e:"O trecho apresenta um filme, avalia ('diverte', 'lindas', 'animadas') e recomenda. Isso é uma resenha! 🍿"},
{n:"m",t:"Gêneros textuais",q:"Qual característica é típica de uma reportagem?",a:["Contar uma história inventada que começa com 'Era uma vez'","Ser escrita em versos que rimam no final","Narrar a vida de uma pessoa desde o nascimento","Aprofundar um fato real com entrevistas e dados"],c:3,e:"A reportagem investiga um fato real com mais detalhes: traz entrevistas, números, pesquisas e fotos. 📰🎤"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nToda escola deveria ter uma horta. Primeiro, porque os alunos aprendem de onde vêm os alimentos. Além disso, quem planta as próprias verduras tem mais vontade de comê-las.\nEsse trecho pertence a qual gênero textual?",a:["artigo de opinião","biografia","poema","texto narrativo"],c:0,e:"O autor defende uma ideia ('toda escola deveria ter uma horta') e dá argumentos ('primeiro...', 'além disso...'). Isso é artigo de opinião! 🥕"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nAlberto Santos Dumont nasceu em 1873, em Minas Gerais. Ainda jovem, mudou-se para Paris, onde construiu balões e aviões. Em 1906, voou com o 14-Bis diante de uma multidão.\nEsse trecho pertence a qual gênero textual?",a:["resenha","biografia","crônica","artigo de opinião"],c:1,e:"O texto conta a vida de uma pessoa real, em 3ª pessoa, com datas e em ordem cronológica: é uma biografia. ✈️"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nToda manhã, no ônibus lotado, alguém tenta equilibrar o café, a mochila e o celular ao mesmo tempo. Hoje foi a minha vez, e o café venceu. A vida moderna é isso: um malabarismo antes das oito.\nEsse trecho pertence a qual gênero textual?",a:["reportagem","poema","biografia","crônica"],c:3,e:"Um fato simples do dia a dia, contado com humor e uma reflexão no final: é uma crônica! ☕🚌"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nO beija-flor é a única ave capaz de voar para trás. Suas asas batem tão rápido que, muitas vezes, nem conseguimos vê-las direito.\nEsse trecho pertence a qual gênero textual?",a:["texto informativo","crônica","poema","resenha"],c:0,e:"O trecho apresenta informações reais sobre um animal, sem opinião nem história inventada: é um texto informativo. 🐦"},
{n:"m",t:"Gêneros textuais",q:"Leia:\nA chuva cai no telhado,\ntoc, toc, toc, sem parar.\nO gato dorme enrolado,\nsonhando em pescar no mar.\nQual par de palavras rima nesse poema?",a:["chuva e gato","telhado e mar","dorme e sonhando","telhado e enrolado"],c:3,e:"'Telhado' e 'enrolado' terminam com o mesmo som (-ado). No poema, 'parar' e 'mar' também rimam! 🎶"},
{n:"m",t:"Substantivo",q:"Na frase 'A coragem do bombeiro salvou a família.', qual é o substantivo abstrato?",a:["bombeiro","coragem","família","salvou"],c:1,e:"Coragem é uma qualidade: ela só existe em alguém (no bombeiro). Por isso é abstrato. Bombeiro e família são concretos. 🚒"},
{n:"m",t:"Substantivo",q:"Na frase 'Um bando de pássaros pousou na árvore.', qual é o substantivo coletivo?",a:["pássaros","árvore","bando","pousou"],c:2,e:"'Bando' é o coletivo que indica um grupo de pássaros. Mesmo no singular, ele representa vários seres! 🐦🐦🐦"},
{n:"m",t:"Substantivo",q:"Na frase 'O jardineiro regou as plantas.', o substantivo 'jardineiro' é derivado de...",a:["jarra","planta","regar","jardim"],c:3,e:"Jardineiro é quem cuida do jardim. A palavra nasceu de 'jardim', que é a primitiva. 🌻"},
{n:"m",t:"Substantivo",q:"Passe para o feminino: 'O rei e o príncipe visitaram o castelo.'",a:["A reia e a príncipa visitaram o castelo.","A rainha e a princesa visitaram o castelo.","A rainha e a príncipe visitaram o castelo.","A rei e a princesa visitaram o castelo."],c:1,e:"Rei → rainha e príncipe → princesa. São femininos com formas especiais! 👑"},
{n:"m",t:"Substantivo",q:"Passe para o plural: 'O cão latiu para o leão.'",a:["Os cãos latiram para os leães.","Os cões latiram para os leões.","Os cães latiram para os leães.","Os cães latiram para os leões."],c:3,e:"Cão → cães e leão → leões. As palavras em -ão podem fazer o plural em -ãos, -ães ou -ões, por isso é bom consultar o dicionário!"},
{n:"m",t:"Substantivo",q:"Na frase 'A saudade da avó fez Júlia chorar.', os substantivos 'saudade' e 'avó' são, respectivamente...",a:["abstrato e concreto","concreto e abstrato","abstrato e abstrato","concreto e concreto"],c:0,e:"Saudade é um sentimento (abstrato). A avó é um ser que existe por si mesmo (concreto). 💛"},
{n:"m",t:"Substantivo",q:"Qual coletivo completa a frase 'A ___ tocou no teatro, e todos os músicos foram aplaudidos.'?",a:["tripulação","orquestra","constelação","biblioteca"],c:1,e:"Orquestra é o coletivo de músicos. Tripulação é de marinheiros ou aeronautas, constelação é de estrelas e biblioteca é de livros. 🎻"},
{n:"m",t:"Aposto e vocativo",q:"Em qual frase há vocativo?",a:["As crianças guardaram os brinquedos.","Os brinquedos das crianças sumiram.","Crianças, guardem os brinquedos.","As crianças, cansadas, dormiram."],c:2,e:"Em 'Crianças, guardem os brinquedos', alguém está chamando as crianças e falando com elas: 'Crianças' é vocativo."},
{n:"m",t:"Aposto e vocativo",q:"Em qual frase há aposto?",a:["Carlos, defenda o pênalti!","Carlos, o goleiro do time, defendeu o pênalti.","Carlos defendeu o pênalti ontem à tarde.","O goleiro do time defendeu o pênalti no fim do jogo."],c:1,e:"'O goleiro do time' explica quem é Carlos. Termo explicativo entre vírgulas é aposto. Em 'Carlos, defenda o pênalti!', Carlos é vocativo. 🧤"},
{n:"m",t:"Aposto e vocativo",q:"Na frase 'Professora, posso ir ao banheiro?', a palavra 'Professora' é vocativo porque...",a:["explica quem é a professora da turma","indica uma ação do aluno","dá uma qualidade ao aluno","chama a pessoa com quem se fala"],c:3,e:"O aluno está chamando a professora para fazer o pedido. Chamar = vocativo! 🙋"},
{n:"m",t:"Aposto e vocativo",q:"Na frase 'Meu tio, um médico famoso, mora em Curitiba.', qual termo é o aposto?",a:["Meu tio","um médico famoso","mora em Curitiba","Curitiba"],c:1,e:"'Um médico famoso' explica quem é o tio. Está entre vírgulas e se refere a 'Meu tio': é aposto. 🩺"},
{n:"m",t:"Aposto e vocativo",q:"Na frase 'Comprei três frutas: maçã, banana e uva.', o aposto 'maçã, banana e uva' vem depois de qual sinal?",a:["vírgula","ponto de exclamação","dois-pontos","travessão"],c:2,e:"Aqui o aposto enumera (lista) quais são as três frutas e vem depois dos dois-pontos. 🍎🍌🍇"},
{n:"m",t:"Aposto e vocativo",q:"Qual frase está pontuada corretamente, com o vocativo separado por vírgula?",a:["Conte, vovô uma história!","Vovô conte uma história, agora!","Conte uma, história vovô!","Vovô, conte uma história!"],c:3,e:"O vocativo 'Vovô' deve ser separado do resto da frase por vírgula: 'Vovô, conte uma história!'. 👴📖"},
{n:"m",t:"Aposto e vocativo",q:"Na frase 'Venham logo, meninos, o ônibus vai partir!', qual é o vocativo?",a:["meninos","Venham","o ônibus","logo"],c:0,e:"Quem fala está chamando os meninos. O vocativo pode aparecer no começo, no meio ou no fim da frase, sempre separado por vírgula. 🚌"},
{n:"m",t:"Adjetivo",q:"Na frase 'O leão é mais forte que o gato.', o adjetivo 'forte' está no grau...",a:["comparativo de igualdade","comparativo de superioridade","comparativo de inferioridade","superlativo"],c:1,e:"A frase compara dois seres e diz que um é MAIS forte que o outro: comparativo de superioridade. 🦁"},
{n:"m",t:"Adjetivo",q:"Na frase 'Esta sobremesa está deliciosíssima!', o adjetivo está no grau...",a:["superlativo","comparativo de igualdade","comparativo de superioridade","comparativo de inferioridade"],c:0,e:"'Deliciosíssima' quer dizer 'muito, muito deliciosa'. O final -íssima mostra o grau superlativo. 🍰"},
{n:"m",t:"Adjetivo",q:"Na frase 'A luz do sol entrou pela janela.', a locução 'do sol' pode ser substituída pelo adjetivo...",a:["ensolarado","solado","solitário","solar"],c:3,e:"Luz do sol = luz solar. 'Do sol' é uma locução adjetiva, e o adjetivo equivalente é 'solar'. ☀️"},
{n:"m",t:"Adjetivo",q:"Qual frase tem o adjetivo concordando corretamente com o substantivo?",a:["As meninas estavam animados.","As meninas estavam animada.","As meninas estavam animadas.","As menina estavam animadas."],c:2,e:"O adjetivo concorda com o substantivo: 'meninas' é feminino e plural, então fica 'animadas'. 👧👧"},
{n:"m",t:"Adjetivo",q:"Na frase 'O paciente tem um problema do coração.', a locução 'do coração' equivale ao adjetivo...",a:["cordial","cardíaco","cardinal","coracional"],c:1,e:"Problema do coração = problema cardíaco. Cuidado: 'cordial' significa gentil, educado. ❤️"},
{n:"m",t:"Artigo",q:"Compare: 'Comprei o livro.' e 'Comprei um livro.' Qual é a diferença de sentido?",a:["'O' indica vários livros; 'um' indica só um","'O' indica um livro já conhecido; 'um', um livro qualquer","Não há nenhuma diferença de sentido","'Um' indica um livro já conhecido; 'o', um livro qualquer"],c:1,e:"O artigo definido (o) fala de algo já conhecido. O indefinido (um) fala de algo qualquer, não específico. 📘"},
{n:"m",t:"Artigo",q:"Na frase 'Fomos à praia no domingo.', a palavra 'no' é a junção de...",a:["em + o","no + o","em + um","de + o"],c:0,e:"'No' junta a preposição 'em' com o artigo 'o': em + o = no. Do mesmo jeito, em + a = na."},
{n:"m",t:"Artigo",q:"Na frase 'O amanhecer na praia foi lindo.', o artigo 'O' faz a palavra 'amanhecer' funcionar como...",a:["verbo","adjetivo","substantivo","preposição"],c:2,e:"'Amanhecer' normalmente é verbo, mas, com o artigo antes, vira o nome de uma coisa: um substantivo. O artigo tem esse poder! 🌅"},
{n:"m",t:"Preposição",q:"Na frase 'Viajamos de avião para Recife.', a preposição 'de' indica...",a:["companhia","tempo","meio","finalidade"],c:2,e:"'De avião' mostra COMO viajamos, ou seja, o meio de transporte. ✈️"},
{n:"m",t:"Preposição",q:"Na frase 'Estudei muito para a prova.', a preposição 'para' indica...",a:["finalidade","companhia","lugar","meio"],c:0,e:"Estudei para quê? Para a prova! A preposição 'para' mostra o objetivo, ou seja, a finalidade. 🎯"},
{n:"m",t:"Preposição",q:"Na frase 'A aula começa às oito horas.', a palavra 'às' indica...",a:["lugar","tempo","companhia","finalidade"],c:1,e:"'Às oito horas' mostra QUANDO a aula começa: indica tempo. 'Às' é a junção da preposição 'a' com o artigo 'as'. ⏰"},
{n:"m",t:"Preposição",q:"Na frase 'O gato dormiu sob a cama.', a preposição 'sob' significa...",a:["em cima de","ao lado de","dentro de","embaixo de"],c:3,e:"Sob = embaixo de. Não confunda com 'sobre', que quer dizer 'em cima de'. 🐈"},
{n:"m",t:"Preposição",q:"Complete corretamente: 'Gustavo passou ___ parque e depois foi ___ escola.'",a:["pela / ao","pelo / à","pelo / ao","pela / à"],c:1,e:"'Parque' é masculino: por + o = pelo. 'Escola' é feminino: a + a = à (com crase). 🏫"},
{n:"m",t:"Verbo",q:"Em qual frase o verbo está no modo subjuntivo?",a:["Você veio à festa ontem.","Espero que você venha à festa.","Venha à festa amanhã!","Você virá à festa amanhã."],c:1,e:"'Espero que você venha' expressa um desejo, algo que ainda não é certo. Desejo e dúvida = subjuntivo. 🎉"},
{n:"m",t:"Verbo",q:"Em qual frase o verbo está no modo imperativo?",a:["Ele desligou a luz ao sair.","Talvez ele desligue a luz.","Ela desliga a luz sempre.","Desligue a luz ao sair."],c:3,e:"'Desligue a luz ao sair' é uma ordem ou pedido: modo imperativo. 'Talvez ele desligue' expressa dúvida: subjuntivo. 💡"},
{n:"m",t:"Verbo",q:"Na frase 'Se eu tivesse asas, voaria até as nuvens.', o verbo 'tivesse' está no subjuntivo porque expressa...",a:["uma certeza","uma hipótese","uma ordem","um fato real"],c:1,e:"Ninguém tem asas de verdade! 'Se eu tivesse' imagina uma situação: é uma hipótese, marca do modo subjuntivo. 🕊️"},
{n:"m",t:"Verbo",q:"Na frase 'Quando eu crescer, serei astronauta.', o verbo 'crescer' está no...",a:["presente do indicativo","imperativo afirmativo","futuro do subjuntivo","pretérito do indicativo"],c:2,e:"'Quando eu crescer' fala de algo que ainda vai acontecer, depois da palavra 'quando': é o futuro do subjuntivo, como em 'quando eu estudar'. 🚀"},
{n:"m",t:"Verbo",q:"Complete o aviso com o imperativo negativo correto (você): '___ na grama!'",a:["Não pise","Não pisa","Não pisou","Não pisará"],c:0,e:"No imperativo negativo com 'você', usamos a forma do subjuntivo: não pise, não corra, não grite. 🚫🌱"},
{n:"m",t:"Verbo",q:"Na frase 'Nós plantávamos flores todo ano.', o verbo está no...",a:["presente do indicativo","futuro do indicativo","pretérito do indicativo","presente do subjuntivo"],c:2,e:"'Plantávamos' mostra uma ação que acontecia no passado e se repetia: é o pretérito do indicativo. 🌷"},
{n:"m",t:"Verbo",q:"Complete com o verbo no modo subjuntivo: 'Tomara que ___ sol amanhã!'",a:["faça","fez","fará","faz"],c:0,e:"'Tomara que' expressa desejo e pede o subjuntivo: tomara que faça sol! ☀️"},
{n:"m",t:"Verbo",q:"Complete: 'Se eu ___ mais cedo, não perderia o ônibus.'",a:["acordo","acordei","acordasse","acordarei"],c:2,e:"'Se eu acordasse' imagina uma situação diferente da real: é uma hipótese, no pretérito do subjuntivo. ⏰🚌"},
{n:"m",t:"Verbo",q:"Na frase 'Amanhã nós iremos ao museu.', o verbo está no...",a:["futuro do indicativo","presente do indicativo","futuro do subjuntivo","modo imperativo"],c:0,e:"'Iremos' fala de algo que vai acontecer, com certeza: futuro do indicativo. 🏛️"},
{n:"m",t:"Verbo",q:"Leia a receita:\nMisture a farinha com o leite e leve ao forno por 30 minutos.\nOs verbos 'misture' e 'leve' estão no imperativo porque...",a:["contam fatos que já passaram","expressam dúvida","dão instruções ao leitor","descrevem sentimentos"],c:2,e:"Em receitas e manuais, o imperativo é usado para orientar o leitor sobre o que fazer. 🧁"},
{n:"m",t:"Pronome",q:"Na frase 'Vi Marina na praça e a cumprimentei.', o pronome 'a' substitui...",a:["a praça","Marina","eu","o cumprimento"],c:1,e:"Quem foi cumprimentada? Marina! O pronome oblíquo 'a' está no lugar de 'Marina' e evita repetir o nome. 👋"},
{n:"m",t:"Pronome",q:"Qual opção evita a repetição em 'O menino perdeu o boné. O menino ficou triste.'?",a:["O menino perdeu o boné. Ela ficou triste.","O menino perdeu o boné. Eles ficou triste.","O menino perdeu o boné. Ele ficou triste.","O menino perdeu o boné. Nós ficamos tristes."],c:2,e:"'Ele' substitui 'o menino' (masculino, singular) e evita repetir a palavra. Essa é uma das funções do pronome! 🧢"},
{n:"m",t:"Pronome",q:"Complete: 'Veja ___ desenho que estou segurando!'",a:["este","esse","aquele","aqueles"],c:0,e:"O desenho está nas mãos de quem fala, ou seja, perto dele. Para o que está perto de quem fala, usamos 'este'. ✏️"},
{n:"m",t:"Pronome",q:"Ao escrever uma carta para o Presidente da República, qual pronome de tratamento devemos usar?",a:["Vossa Santidade","Vossa Majestade","você","Vossa Excelência"],c:3,e:"Para presidentes, governadores, prefeitos e outras altas autoridades, usamos 'Vossa Excelência'. 🏛️"},
{n:"m",t:"Pronome",q:"Na frase 'Nossa escola ganhou o campeonato.', o pronome possessivo 'Nossa' indica posse de qual pessoa?",a:["1ª pessoa do singular (eu)","1ª pessoa do plural (nós)","2ª pessoa do singular (tu)","3ª pessoa do plural (eles)"],c:1,e:"'Nossa' quer dizer 'de nós': a escola pertence a nós. Nós = 1ª pessoa do plural. 🏆"},
{n:"m",t:"Pronome",q:"Complete conforme a norma padrão: 'Este presente é para ___.'",a:["eu","mim","me","comigo"],c:1,e:"Depois de preposição (para, de, sem...), usamos 'mim': 'para mim', 'sem mim'. 🎁"},
{n:"m",t:"Pronome",q:"Na frase 'Aquela bicicleta é minha.', o pronome 'Aquela'...",a:["substitui o substantivo 'bicicleta'","indica uma ação de alguém","é um pronome pessoal do caso oblíquo","acompanha o substantivo 'bicicleta'"],c:3,e:"'Aquela' vem junto do substantivo 'bicicleta', acompanhando-o e mostrando que ela está longe de quem fala. 🚲"},
{n:"m",t:"Numeral",q:"Na frase 'Dom Pedro II governou o Brasil por muitos anos.', como se lê 'Dom Pedro II'?",a:["Dom Pedro Dois","Dom Pedro Segundo","Dom Pedro Onze","Dom Pedro Décimo Primeiro"],c:1,e:"Para reis e papas, lemos com ordinal até o décimo: Pedro II = Pedro Segundo. 👑"},
{n:"m",t:"Numeral",q:"No livro, a professora pediu: 'Leiam o capítulo IX.' Qual número o 'IX' representa?",a:["onze","nove","quatro","seis"],c:1,e:"Em números romanos, o I antes do X tira um: X (10) − I (1) = 9. Então 'capítulo IX' é o capítulo nove."},
{n:"m",t:"Numeral",q:"Na frase 'Comi um terço da pizza.', a palavra 'terço' é um numeral...",a:["ordinal","multiplicativo","cardinal","fracionário"],c:3,e:"Um terço é uma das três partes iguais de algo. Indica divisão, então é fracionário. Cuidado: 'terceiro' é ordinal! 🍕"},
{n:"m",t:"Numeral",q:"Na frase 'Lucas fez o triplo de pontos do irmão.', a palavra 'triplo' é um numeral...",a:["fracionário","multiplicativo","ordinal","cardinal"],c:1,e:"Triplo = três vezes mais. Indica multiplicação, por isso é multiplicativo. 🎯"},
{n:"m",t:"Numeral",q:"Como se lê 'século XIX'?",a:["século vinte e um","século onze","século dezenove","século quatorze"],c:2,e:"XIX = X + IX = 10 + 9 = 19. Como passa de dez, lemos com cardinal: século dezenove."},
{n:"m",t:"Numeral",q:"Qual é o numeral ordinal que corresponde a 20º?",a:["vigésimo","vintésimo","duodécimo","vigentésimo"],c:0,e:"20º se escreve 'vigésimo'. Outros exemplos: 10º décimo, 30º trigésimo. 🥇"},
{n:"d",t:"Interpretação de texto",q:"Leia:\n— Que dia maravilhoso! — resmungou Caio, olhando a chuva forte que tinha cancelado o passeio da escola.\nO que Caio quis dizer?",a:["Ele adorou ver a chuva forte","Ele achou o passeio maravilhoso","Ele usou ironia: estava chateado","Ele não sabia que estava chovendo"],c:2,e:"Caio 'resmungou' e o passeio foi cancelado: ele estava chateado. Dizer o contrário do que se sente, para mostrar insatisfação, é ironia. 🙄"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nNa cidade de Pedra Alta, o rio secou pela primeira vez em cem anos. Os pescadores, sem trabalho, passaram a plantar mandioca. Mas o velho Tião continuava indo à margem todas as manhãs, com a vara de pescar no ombro.\nO que a atitude de Tião sugere?",a:["Que ele tinha esperança de que o rio voltasse","Que ele plantava muito mais mandioca que todos","Que ele não sabia pescar direito","Que o rio estava cheio de peixes"],c:0,e:"Mesmo com o rio seco, Tião continuava indo pescar: isso sugere esperança. A palavra 'Mas' mostra que ele agiu diferente dos outros pescadores. 🎣"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nAs mãos do avô eram ásperas de tanto trabalhar na roça, mas o carinho delas era o mais macio do mundo.\nO que o autor quis destacar?",a:["Que o avô tinha mãos muito macias","Que, mesmo com mãos ásperas, o avô era carinhoso","Que o avô não gostava nada de trabalhar na roça","Que o carinho do avô machucava os netos pequenos"],c:1,e:"O 'mas' faz um contraste: as mãos eram ásperas (duras), porém o carinho era 'macio'. O autor destaca a ternura do avô. 👴❤️"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nO lixo jogado nas ruas entope os bueiros. Quando chove, a água não tem por onde escoar e as ruas alagam. Por isso, jogar o lixo no lugar certo também ajuda a evitar enchentes.\nQual seria o melhor título para esse texto?",a:["Como construir um bueiro","A chuva é sempre perigosa","As ruas mais bonitas e limpas da cidade","Lixo no lugar certo evita enchentes"],c:3,e:"Um bom título resume a ideia principal. O texto todo mostra a ligação entre o lixo nas ruas e as enchentes. 🗑️🌧️"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nComo tinha esquecido o protetor solar, Bia passou a tarde na sombra do guarda-sol, enquanto os primos brincavam na areia.\nNesse trecho, a palavra 'Como' tem sentido de...",a:["comparação (igual a)","causa (porque)","tempo (quando)","pergunta (de que modo)"],c:1,e:"'Como tinha esquecido o protetor' = 'Porque tinha esquecido o protetor'. É a causa de Bia ficar na sombra. ⛱️"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nO parque da cidade tem 30 árvores frutíferas e uma pista de caminhada. Na minha opinião, é o lugar mais bonito do bairro.\nQual trecho é uma OPINIÃO, e não um fato?",a:["O parque tem 30 árvores frutíferas","O parque tem uma pista de caminhada","É o lugar mais bonito do bairro","O parque fica na cidade"],c:2,e:"Fato é algo que pode ser verificado (contar as árvores, ver a pista). Achar que é 'o lugar mais bonito' depende do gosto de cada um: é opinião. 🌳"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nA tartaruga e o coelho apostaram uma corrida. Ele saiu na frente, mas parou para dormir. Ela seguiu devagar e venceu.\nNo texto, a palavra 'Ela' se refere a...",a:["a corrida","o coelho","a aposta","a tartaruga"],c:3,e:"Quem 'seguiu devagar e venceu' foi a tartaruga. O pronome 'Ela' retoma 'a tartaruga' e evita repetir a palavra. 🐢🏁"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nPROCURA-SE: gatinho cinza, de olhos verdes, que atende pelo nome de Fumaça. Sumiu no sábado, perto da padaria. Quem encontrar, ligue para a Júlia!\nPor que o texto descreve a cor do pelo e dos olhos do gato?",a:["Para ajudar as pessoas a reconhecer o gato","Para mostrar que o gato está à venda","Para ensinar como cuidar de gatos","Para comparar o gato com outros animais da rua"],c:0,e:"Num cartaz de 'procura-se', a descrição ajuda quem ler a reconhecer o gato se o encontrar. Cada detalhe tem uma finalidade! 🐱🔎"},
{n:"d",t:"Interpretação de texto",q:"Leia:\nQuando o time marcou o gol no último minuto, o estádio explodiu de alegria.\nA expressão 'o estádio explodiu de alegria' significa que...",a:["o estádio foi destruído","os torcedores comemoraram muito","soltaram fogos dentro do campo","a partida foi cancelada pelo juiz"],c:1,e:"É linguagem figurada: o estádio não explodiu de verdade! A expressão mostra que a torcida vibrou e comemorou muito. ⚽🎉"},
{n:"d",t:"Gêneros textuais",q:"Qual é a principal diferença entre uma reportagem e uma crônica?",a:["A reportagem é escrita em versos; a crônica, em parágrafos curtos","A reportagem investiga fatos com dados; a crônica comenta o cotidiano","A reportagem conta histórias inventadas; a crônica só traz números","A reportagem avalia filmes; a crônica conta a vida de pessoas famosas"],c:1,e:"A reportagem informa e investiga um fato real com dados e entrevistas. A crônica parte de algo do dia a dia e traz um olhar pessoal, leve e às vezes engraçado."},
{n:"d",t:"Gêneros textuais",q:"Leia:\nNasci em uma pequena cidade do interior, em 1980. Aos sete anos, aprendi a ler com minha avó.\nEsse trecho é de uma AUTObiografia, e não de uma biografia, porque...",a:["apresenta datas e fatos importantes da vida","fala sobre a infância de alguém","usa 'eu': quem conta é a própria pessoa","é um texto sobre uma pessoa real"],c:2,e:"Na autobiografia, a própria pessoa conta sua vida, usando 'eu' (1ª pessoa). Na biografia, outra pessoa conta, em 3ª pessoa. Datas e fatos aparecem nas duas. 📖"},
{n:"d",t:"Gêneros textuais",q:"Leia:\nCecília Meireles nasceu no Rio de Janeiro, em 1901. Tornou-se professora e uma das maiores poetas do Brasil.\nComo esse trecho de biografia é narrado?",a:["Em 3ª pessoa, por outra pessoa","Em 1ª pessoa, pela própria Cecília","Em versos, com rimas","Em forma de entrevista"],c:0,e:"O texto diz 'nasceu', 'tornou-se': é a 3ª pessoa. Na biografia, alguém conta a vida de outra pessoa real, em ordem cronológica. 📚"},
{n:"d",t:"Gêneros textuais",q:"Leia:\nO livro 'A Ilha dos Relógios' conta a história de Nina, uma menina que descobre um lugar onde o tempo para. Os capítulos são curtos e cheios de mistério. Indico para quem gosta de aventura!\nQual trecho mostra a RECOMENDAÇÃO de quem escreveu a resenha?",a:["'conta a história de Nina'","'Indico para quem gosta de aventura!'","'uma menina que descobre um lugar onde o tempo para'","'O livro A Ilha dos Relógios'"],c:1,e:"Na resenha, primeiro se apresenta a obra, depois vem a avaliação ('curtos e cheios de mistério') e a recomendação: 'Indico para quem gosta de aventura!'. ⏰📗"},
{n:"d",t:"Gêneros textuais",q:"Leia:\nAs crianças deveriam ter mais aulas de educação física. Praticar esportes melhora a saúde, ajuda na concentração e ensina a trabalhar em equipe.\nQual é a opinião principal (tese) defendida no texto?",a:["Praticar esportes melhora a saúde e a concentração das crianças","Esportes ensinam a trabalhar em equipe","A concentração é importante na escola","As crianças deveriam ter mais aulas de educação física"],c:3,e:"A tese é a ideia que o autor defende: mais aulas de educação física. As outras frases são argumentos que apoiam essa opinião. 🏃‍♀️"},
{n:"d",t:"Gêneros textuais",q:"Leia:\nOs celulares não deveriam ser usados durante as aulas. Eles tiram a atenção dos alunos e atrapalham as explicações do professor.\nNesse artigo de opinião, a frase 'Eles tiram a atenção dos alunos' funciona como...",a:["um argumento que defende a opinião","o título que resume o artigo","uma informação sobre a vida do autor","o desfecho de uma história"],c:0,e:"Argumento é uma razão que o autor usa para convencer o leitor. Aqui, ele explica POR QUE os celulares não deveriam ser usados nas aulas. 📵"},
{n:"d",t:"Gêneros textuais",q:"Leia:\nMeu vizinho rega as plantas às seis da manhã cantando ópera. Os passarinhos já desistiram de competir. Às vezes penso que o bairro inteiro acorda não pelo despertador, mas pelo seu Alfredo.\nQuais características mostram que esse trecho é uma crônica?",a:["Dados numéricos, entrevistas e gráficos","Versos, estrofes e rimas","Fato do cotidiano, linguagem leve e humor","Datas importantes da vida de uma pessoa famosa"],c:2,e:"A crônica parte de uma cena comum do dia a dia (o vizinho regando plantas) e a conta com leveza, humor e um toque de reflexão. 🎶🌿"},
{n:"d",t:"Gêneros textuais",q:"Leia o poema:\nNa janela da cozinha\nmora um vaso de alecrim.\nCheira a festa, cheira a tarde,\ncheira a vovó e a mim.\n\nQuando a chuva vem chegando,\nele dança no peitoril,\ne o seu cheiro sai voando\npela casa em mês de abril.\nQuantas estrofes e quantos versos tem esse poema?",a:["8 estrofes e 2 versos","2 estrofes e 4 versos","1 estrofe e 8 versos","2 estrofes e 8 versos"],c:3,e:"Cada linha é um verso (8 no total) e cada bloco de versos é uma estrofe (2 blocos, separados pelo espaço em branco). 🌿"},
{n:"d",t:"Gêneros textuais",q:"Qual é a ordem mais comum das partes de uma narrativa?",a:["clímax, situação inicial, desfecho, conflito","situação inicial, conflito, clímax, desfecho","desfecho, conflito, situação inicial, clímax","conflito, desfecho, clímax, situação inicial"],c:1,e:"Primeiro conhecemos personagens e lugar (situação inicial), depois surge um problema (conflito), a tensão chega ao máximo (clímax) e tudo se resolve (desfecho). 📖"},
{n:"d",t:"Gêneros textuais",q:"Leia:\nZeca e Duda construíram uma casa na árvore. Tudo ia bem até que uma tempestade derrubou o telhado. Os dois trabalharam juntos o fim de semana inteiro e, no domingo, a casa estava mais bonita do que antes.\nQual é o CONFLITO dessa narrativa?",a:["A tempestade derrubou o telhado","Zeca e Duda construíram uma casa","A casa ficou mais bonita no domingo","Os dois trabalharam o fim de semana"],c:0,e:"O conflito é o problema que quebra a situação inicial: a tempestade derrubando o telhado. O trabalho dos dois e a casa ainda mais bonita levam ao desfecho. 🌳🏠"},
{n:"d",t:"Gêneros textuais",q:"Leia:\nUma pesquisa feita em 20 escolas da cidade mostrou que 7 em cada 10 alunos tomam café da manhã antes da aula. Segundo a nutricionista Marta Lima, essa refeição melhora a atenção.\nQuais elementos mostram que o trecho é de uma reportagem?",a:["Rimas e versos no final das linhas","Opinião pessoal sobre um filme","Dados de pesquisa e fala de especialista","Personagens imaginários e a expressão 'Era uma vez'"],c:2,e:"A reportagem aprofunda um assunto real usando dados (pesquisa em 20 escolas) e falas de entrevistados ou especialistas (a nutricionista). 📊🎤"},
{n:"d",t:"Substantivo",q:"Na frase 'A fada realizou o desejo da menina.', os substantivos 'fada' e 'desejo' são, respectivamente...",a:["abstrato e concreto","concreto e abstrato","abstrato e abstrato","concreto e concreto"],c:1,e:"Mesmo sendo imaginária, a fada é concreta: nas histórias ela existe por si mesma. Já o desejo depende de alguém para existir: é abstrato. 🧚"},
{n:"d",t:"Substantivo",q:"Qual é o plural correto de 'couve-flor'?",a:["couve-flores","couves-flor","couves-flores","couve-flor (não muda)"],c:2,e:"Couve-flor é formado por dois substantivos. Quando as duas partes são substantivos, as duas vão para o plural: couves-flores. 🥦🥦"},
{n:"d",t:"Substantivo",q:"Qual alternativa apresenta o plural correto de 'mão', 'balão' e 'alemão'?",a:["mães, balãos, alemões","mões, balões, alemãos","mãos, balães, alemões","mãos, balões, alemães"],c:3,e:"Cada palavra em -ão tem seu plural: mão → mãos, balão → balões, alemão → alemães. Na dúvida, consulte o dicionário! 🎈"},
{n:"d",t:"Substantivo",q:"Na frase 'A criança chegou atrasada.', como indicar que a criança é um menino?",a:["Trocar o artigo: 'o criança'","Não muda: serve para os dois","Mudar a palavra para 'crianço'","Trocar para 'o crianço' na frase"],c:1,e:"'Criança' é um substantivo sobrecomum: tem uma só forma e um só artigo para menino e menina. Outros exemplos: a vítima, o indivíduo."},
{n:"d",t:"Substantivo",q:"Em qual substantivo basta trocar o artigo para indicar masculino ou feminino, como em 'o estudante / a estudante'?",a:["artista","mulher","boi","rei"],c:0,e:"'O artista / a artista': a palavra não muda, só o artigo. É um substantivo comum de dois gêneros. Já boi → vaca e rei → rainha mudam a palavra. 🎨"},
{n:"d",t:"Substantivo",q:"Qual alternativa tem APENAS palavras derivadas de 'pão'?",a:["padaria, pato, pãozinho","padre, padeiro, pão","panela, padeiro, padaria","padaria, padeiro, pãozinho"],c:3,e:"Padaria, padeiro e pãozinho vêm de 'pão'. Pato, padre e panela só se parecem com 'pão', mas não vêm dele. E 'pão' é a palavra primitiva, não derivada. 🥖"},
{n:"d",t:"Aposto e vocativo",q:"Compare:\n(1) Ana, a minha prima chegou.\n(2) Ana, a minha prima, chegou.\nO que muda entre as frases?",a:["Nas duas, 'Ana' é vocativo","Em (1), 'Ana' é vocativo; em (2), 'a minha prima' é aposto","Em (1), 'a minha prima' é aposto; em (2), 'Ana' é vocativo","Nada muda: a vírgula não altera o sentido"],c:1,e:"Em (1), alguém chama Ana para avisar que a prima chegou: vocativo. Em (2), 'a minha prima' explica quem é Ana, que chegou: aposto. Uma vírgula muda tudo! 😮"},
{n:"d",t:"Aposto e vocativo",q:"Qual frase tem, ao mesmo tempo, vocativo e aposto?",a:["Júlia, venha brincar com a gente!","Rafael, meu vizinho, quer brincar.","Júlia, o Rafael, seu vizinho, quer brincar.","O vizinho da Júlia quer muito brincar com ela hoje."],c:2,e:"'Júlia' é vocativo (alguém fala com ela) e 'seu vizinho' é aposto (explica quem é Rafael). Em 'Rafael, meu vizinho, quer brincar' só há aposto. 🤝"},
{n:"d",t:"Aposto e vocativo",q:"Na frase 'Minha comida favorita — lasanha — é feita pela minha avó.', o termo entre travessões é...",a:["vocativo, pois chama a avó","aposto, pois explica qual é a comida","vocativo, pois chama a lasanha","adjetivo, pois dá uma qualidade à comida"],c:1,e:"'Lasanha' especifica qual é a comida favorita. O aposto pode vir entre vírgulas, entre travessões ou depois de dois-pontos. 🍝"},
{n:"d",t:"Aposto e vocativo",q:"Em qual frase o aposto está pontuado corretamente?",a:["Cândido Portinari um pintor famoso, nasceu em Brodowski.","Anita Malfatti, uma pintora paulista nasceu em São Paulo.","Tarsila do Amaral, uma grande pintora brasileira, nasceu no interior paulista.","Di Cavalcanti, um pintor carioca nasceu, no Rio de Janeiro."],c:2,e:"No meio da frase, o aposto precisa ficar entre duas vírgulas, uma antes e outra depois: 'Tarsila do Amaral, uma grande pintora brasileira, nasceu...'. Nas outras, falta uma vírgula ou ela está no lugar errado. 🎨"},
{n:"d",t:"Aposto e vocativo",q:"Na frase 'Não se esqueça do casaco, filho.', qual é a função de 'filho'?",a:["aposto, pois explica o que é o casaco","aposto, pois explica quem esqueceu","adjetivo, pois dá qualidade ao casaco","vocativo, pois chama o ouvinte"],c:3,e:"Quem fala está se dirigindo diretamente ao filho: é vocativo. Ele pode vir no fim da frase, separado por vírgula. 🧥"},
{n:"d",t:"Aposto e vocativo",q:"Na frase 'Netuno, o planeta mais distante do Sol, é muito frio.', o que acontece se retirarmos o aposto?",a:["A frase fica sem sentido e precisa ser reescrita","A frase continua certa, mas com menos informação","A frase passa a ter um vocativo","Netuno passa a ser o planeta mais próximo do Sol"],c:1,e:"O aposto acrescenta uma explicação. Sem ele, 'Netuno é muito frio' continua correta, só fica com menos informação. 🪐"},
{n:"d",t:"Adjetivo",q:"Qual é o superlativo absoluto sintético de 'bom'?",a:["ótimo","melhor","péssimo","bonzíssimo"],c:0,e:"Bom → ótimo (muito bom). 'Melhor' é comparativo ('melhor que') e 'péssimo' é o superlativo de 'mau'. 👍"},
{n:"d",t:"Adjetivo",q:"Qual frase está correta segundo a norma padrão?",a:["Este bolo é mais bom que aquele.","Este bolo é mais melhor que aquele.","Este bolo é mais ótimo que aquele.","Este bolo é melhor que aquele."],c:3,e:"O comparativo de superioridade de 'bom' é 'melhor', e não 'mais bom'. E 'mais melhor' repete a ideia de 'mais'! 🍰"},
{n:"d",t:"Adjetivo",q:"Em qual alternativa a locução adjetiva foi trocada corretamente por um adjetivo?",a:["água de chuva → água chuvosa","amor de pai → amor paterno","atitude de herói → atitude heroizada","jogo de futebol → jogo futeboleiro"],c:1,e:"Amor de pai = amor paterno. O certo seria água pluvial e atitude heroica. 'Chuvoso' é o dia em que chove muito! 🌧️"},
{n:"d",t:"Adjetivo",q:"Qual frase apresenta a concordância correta do adjetivo?",a:["Os meninos e as meninas ficaram cansadas.","Os meninos e as meninas ficaram cansado.","Os meninos e as meninas ficaram cansados.","Os meninos e as meninas ficaram cansada."],c:2,e:"Quando o adjetivo se refere a palavras masculinas e femininas ao mesmo tempo, ele vai para o masculino plural: cansados."},
{n:"d",t:"Adjetivo",q:"Compare: 'O velho amigo chegou.' e 'O velho chegou.' Na segunda frase, a palavra 'velho' é...",a:["adjetivo, pois qualifica o substantivo","substantivo, pois dá nome a um ser","verbo, pois indica uma ação","artigo, pois acompanha o nome"],c:1,e:"Na primeira, 'velho' qualifica 'amigo' (adjetivo). Na segunda, com o artigo 'O', vira o nome de quem chegou: substantivo. A classe depende do uso na frase! 🔄"},
{n:"d",t:"Artigo",q:"Na frase 'Ele tem uns dez anos.', o artigo 'uns' indica...",a:["quantidade exata","um ser já conhecido do leitor","uma ordem","quantidade aproximada"],c:3,e:"'Uns dez anos' = mais ou menos dez anos. O artigo indefinido pode indicar quantidade aproximada. 🤷"},
{n:"d",t:"Artigo",q:"Na frase 'Ele morava numa casa amarela.', a palavra 'numa' é a combinação de...",a:["em + a (artigo definido)","em + uma (artigo indefinido)","no + uma (artigo indefinido)","um + a (artigo definido)"],c:1,e:"'Numa' junta a preposição 'em' com o artigo indefinido 'uma': em + uma = numa. 🏠"},
{n:"d",t:"Artigo",q:"Compare: 'O capital da empresa cresceu.' e 'A capital do país é Brasília.' O que os artigos mostram?",a:["Que as duas palavras significam exatamente a mesma coisa","Que 'capital' é sempre masculino","Que 'capital' tem sentidos diferentes: dinheiro e cidade","Que 'capital' é sempre feminino"],c:2,e:"O capital = dinheiro, bens. A capital = cidade principal. Aqui, o artigo ajuda a mostrar qual é o sentido da palavra! 💰🏙️"},
{n:"d",t:"Preposição",q:"Em qual frase a preposição indica TEMPO?",a:["Vou à escola de bicicleta.","Brinquei com meu irmão.","Estudo desde as sete horas.","O lápis está sobre a mesa."],c:2,e:"'Desde as sete horas' indica a partir de quando: tempo. 'De bicicleta' é meio, 'com meu irmão' é companhia e 'sobre a mesa' é lugar. ⏱️"},
{n:"d",t:"Preposição",q:"Na frase 'Entreguei o bilhete àquela menina.', a palavra 'àquela' é a junção de...",a:["à + quela","a + aquela","há + aquela","a + a + quela"],c:1,e:"'Àquela' junta a preposição 'a' com o pronome 'aquela'. O acento grave (crase) mostra essa junção: a + aquela = àquela. ✉️"},
{n:"d",t:"Preposição",q:"Compare: 'Ela saiu com o irmão.' e 'Ela saiu sem o irmão.' O que a troca da preposição causou?",a:["Passou de companhia para ausência","Não mudou nada no sentido","Mudou o tempo em que ela saiu","Transformou a frase em uma pergunta"],c:0,e:"'Com' indica companhia; 'sem' indica a falta dela. Trocar uma preposição pode mudar todo o sentido da frase! 🔁"},
{n:"d",t:"Preposição",q:"Na frase 'Desde cedo, Lia caminhou até a praia sem o chinelo.', quais são as preposições?",a:["cedo, até, sem","desde, a, o","desde, até, sem","Lia, praia, chinelo"],c:2,e:"Desde, até e sem são preposições. 'A' e 'o', nessa frase, são artigos (a praia, o chinelo). 🏖️"},
{n:"d",t:"Preposição",q:"Nas frases 'Fiz o bolo para a festa.' e 'Fui para a escola.', a preposição 'para' indica, respectivamente...",a:["companhia e tempo","finalidade e direção","tempo e finalidade","lugar e companhia"],c:1,e:"O bolo foi feito para quê? Para a festa: finalidade. Fui para onde? Para a escola: direção (lugar). A mesma preposição pode ter sentidos diferentes! 🎂🏫"},
{n:"d",t:"Verbo",q:"Leia:\nSe você estudar todos os dias, vai aprender muito. Comece hoje! Eu sempre reviso a matéria depois da aula.\nOs verbos 'estudar', 'Comece' e 'reviso' estão, respectivamente, nos modos...",a:["indicativo, subjuntivo e imperativo","subjuntivo, imperativo e indicativo","imperativo, indicativo e subjuntivo","subjuntivo, indicativo e imperativo"],c:1,e:"'Se você estudar' é hipótese (subjuntivo); 'Comece hoje!' é conselho (imperativo); 'Eu sempre reviso' é certeza (indicativo). 📚"},
{n:"d",t:"Verbo",q:"Compare:\n(1) Estude para a prova!\n(2) A mãe quer que ele estude para a prova.\nA forma 'estude' está...",a:["no subjuntivo nas duas frases","no imperativo nas duas frases","no indicativo em (1) e no imperativo em (2)","no imperativo em (1) e no subjuntivo em (2)"],c:3,e:"A forma é igual, mas o uso muda: em (1) é uma ordem ou conselho (imperativo); em (2), depois de 'quer que', expressa desejo (subjuntivo). 🧐"},
{n:"d",t:"Verbo",q:"Nas expressões 'que eu estude', 'se eu estudasse' e 'quando eu estudar', o verbo está no subjuntivo, nos tempos...",a:["presente, pretérito e futuro","futuro, presente e pretérito","pretérito, futuro e presente","presente, futuro e pretérito"],c:0,e:"Que eu estude = presente; se eu estudasse = pretérito; quando eu estudar = futuro. Todos no modo subjuntivo! ✍️"},
{n:"d",t:"Verbo",q:"Em qual frase o verbo 'chover' NÃO indica um fenômeno da natureza?",a:["Choveu forte durante toda a madrugada.","Vai chover amanhã à tarde em toda a cidade.","Choverá no fim de semana.","Choveram perguntas depois da palestra."],c:3,e:"Em 'choveram perguntas', o verbo tem sentido figurado: muitas perguntas foram feitas. Nas outras frases, é chuva de verdade! 🌧️❓"},
{n:"d",t:"Verbo",q:"Complete corretamente: 'Se nós ___ o mapa, não ___ o caminho.'",a:["temos / perderíamos","tivéssemos / perderíamos","tivermos / perdíamos","teremos / perdêssemos"],c:1,e:"'Se nós tivéssemos' (pretérito do subjuntivo) combina com 'perderíamos': é uma hipótese, algo imaginado que não aconteceu. 🗺️"},
{n:"d",t:"Verbo",q:"Complete conforme a norma padrão: 'Quando você ___ (ver) o arco-íris, faça um pedido!'",a:["ver","vê","vir","visse"],c:2,e:"No futuro do subjuntivo, o verbo 'ver' fica 'vir': quando eu vir, quando você vir. 'Quando você ver' é um erro muito comum! 🌈"},
{n:"d",t:"Verbo",q:"Complete com o verbo 'fazer' no futuro do subjuntivo: 'Se você ___ a lição agora, poderá brincar depois.'",a:["fazer","fizer","faz","fará"],c:1,e:"O futuro do subjuntivo de 'fazer' é 'fizer': se eu fizer, se você fizer. 'Se você fazer' está errado! 📝"},
{n:"d",t:"Verbo",q:"Na placa 'Não jogue lixo no chão. Use a lixeira!', os verbos 'jogue' e 'use' estão, respectivamente, no...",a:["imperativo negativo e afirmativo","subjuntivo e indicativo","indicativo e imperativo afirmativo","imperativo afirmativo e subjuntivo"],c:0,e:"As duas frases orientam o leitor. 'Não jogue' é imperativo negativo (proíbe) e 'Use' é imperativo afirmativo (manda fazer). 🗑️"},
{n:"d",t:"Verbo",q:"Qual frase expressa um DESEJO usando o modo subjuntivo?",a:["Meu time venceu o jogo.","Meu time vencerá o jogo de domingo.","Vença o jogo, meu time!","Tomara que meu time vença o jogo!"],c:3,e:"'Tomara que' expressa desejo e pede o subjuntivo: 'vença'. Já 'Vença o jogo, meu time!' é um apelo no imperativo. ⚽"},
{n:"d",t:"Verbo",q:"Leia:\n(1) Talvez chova amanhã.\n(2) Choverá amanhã.\nQual afirmação está correta?",a:["(1) certeza, indicativo; (2) dúvida, subjuntivo","As duas expressam ordem, no imperativo","(1) dúvida, subjuntivo; (2) certeza, indicativo","As duas expressam dúvida, no subjuntivo"],c:2,e:"'Talvez' indica dúvida e pede o subjuntivo (chova). 'Choverá' afirma com certeza: indicativo. 🌦️"},
{n:"d",t:"Pronome",q:"Pedro aponta para o boné que o amigo está usando e pergunta: 'Onde você comprou ___ boné?' Qual pronome completa corretamente?",a:["este","esse","aquele","meu"],c:1,e:"O boné está com o amigo, ou seja, perto de quem ouve. Para isso usamos 'esse'. Este = perto de quem fala; aquele = longe dos dois. 🧢"},
{n:"d",t:"Pronome",q:"Como reescrever 'Eu vi ele na escola.' de acordo com a norma padrão?",a:["Eu lhe vi na escola.","Eu vi-lhe na escola.","Eu o vi na escola.","Eu ele vi na escola."],c:2,e:"Na norma padrão, quem 'é visto' é representado pelo pronome oblíquo 'o': 'Eu o vi'. 'Vi ele' é comum na fala, mas não na escrita formal. 👀"},
{n:"d",t:"Pronome",q:"Complete conforme a norma padrão: 'A professora trouxe o livro para ___ ler.'",a:["eu","mim","me","comigo"],c:0,e:"Quando depois vem um verbo (ler), quem faz a ação é 'eu': 'para eu ler'. Sem verbo depois, usamos 'mim': 'o livro é para mim'. 📖"},
{n:"d",t:"Pronome",q:"Qual frase usa corretamente o pronome de tratamento 'Vossa Excelência'?",a:["Vossa Excelência trouxestes vosso discurso?","Vossa Excelência trouxe vosso discurso?","Vossa Excelência trouxeste teu discurso?","Vossa Excelência trouxe seu discurso?"],c:3,e:"Com os pronomes de tratamento (Vossa Excelência, você...), o verbo e o possessivo ficam na 3ª pessoa: 'trouxe seu discurso'. 🎤"},
{n:"d",t:"Pronome",q:"Leia: 'Lia disse a Bruno que encontrou sua mochila.' Por que essa frase pode gerar dúvida?",a:["Porque 'sua' pode ser a mochila de Lia ou a de Bruno","Porque 'sua' é um pronome demonstrativo, e não possessivo","Porque falta um verbo na frase","Porque 'Lia' é um pronome pessoal"],c:0,e:"O possessivo 'sua' pode se referir a Lia ou a Bruno. Para evitar a dúvida, poderíamos escrever 'a mochila dele' ou 'a mochila dela'. 🎒"},
{n:"d",t:"Pronome",q:"Leia:\nOs pássaros fizeram um ninho na varanda. Mamãe não quis tirá-lo de lá.\nO pronome 'lo', em 'tirá-lo', se refere a...",a:["os pássaros","o ninho","a varanda","Mamãe"],c:1,e:"Mamãe não quis tirar o ninho. O pronome 'lo' (masculino, singular) retoma 'ninho' e evita a repetição. 🪺"},
{n:"d",t:"Pronome",q:"Na frase 'Eu emprestei meu lápis a ela, e ela me devolveu este caderno.', aparecem pronomes...",a:["apenas pessoais","pessoais e de tratamento","pessoais, de tratamento e indefinidos","pessoais, possessivo e demonstrativo"],c:3,e:"Eu, ela e me são pessoais; 'meu' é possessivo; 'este' é demonstrativo. Uma frase pode ter vários tipos de pronome! ✏️📒"},
{n:"d",t:"Numeral",q:"Como se lê o nome do Papa João XXIII?",a:["João Vigésimo Terceiro","João Vinte e Três","João Dezessete","João Vinte e Dois"],c:1,e:"Para papas e reis, usamos ordinal até o décimo e cardinal do onze em diante. XXIII = 23, então lemos 'João Vinte e Três'."},
{n:"d",t:"Numeral",q:"Qual é a regra para ler números romanos depois de nomes de reis, papas e séculos?",a:["Usa-se sempre o numeral ordinal","Usa-se sempre o numeral cardinal","Ordinal até o décimo e cardinal a partir do onze","Cardinal até o dez e ordinal a partir do número onze"],c:2,e:"Exemplos: Pedro II (segundo), século X (décimo), século XXI (vinte e um), Luís XIV (catorze). 📜"},
{n:"d",t:"Numeral",q:"Estamos no ano de 2026. Em que século estamos, e como ele se lê?",a:["Século XXI, lido 'vinte e um'","Século XX, lido 'vinte'","Século XXI, lido 'vigésimo primeiro'","Século XIX, lido 'dezenove'"],c:0,e:"Os anos de 2001 a 2100 formam o século XXI. Como é maior que dez, lemos com cardinal: século vinte e um. 📅"},
{n:"d",t:"Numeral",q:"Ana tem 5 figurinhas e Bia tem o triplo. Quantas figurinhas Bia tem, e que tipo de numeral é 'triplo'?",a:["8, numeral cardinal","15, numeral ordinal","3, numeral fracionário (um terço)","15, numeral multiplicativo"],c:3,e:"Triplo = três vezes: 3 × 5 = 15. Numeral que indica multiplicação é multiplicativo. 🃏"},
{n:"d",t:"Numeral",q:"Compare: 'Ele chegou em quarto lugar.' e 'Comi um quarto do bolo.' A palavra 'quarto' é, respectivamente, numeral...",a:["fracionário e ordinal","ordinal e fracionário","cardinal e multiplicativo","ordinal e multiplicativo"],c:1,e:"'Quarto lugar' indica posição (ordinal). 'Um quarto do bolo' indica uma das quatro partes (fracionário). A mesma palavra, sentidos diferentes! 🍰"},
{n:"d",t:"Numeral",q:"Como se escreve por extenso o numeral ordinal 50º?",a:["cinquentésimo","quintagésimo","quinquagésimo","quinquentésimo"],c:2,e:"50º = quinquagésimo. Outros: 40º quadragésimo, 60º sexagésimo. 🏅"},
{n:"d",t:"Numeral",q:"Na frase 'Leia o capítulo XII do livro.', como se lê 'XII'?",a:["onze","décimo segundo","vinte e dois","doze"],c:3,e:"XII = X + II = 12. Depois do nome (capítulo XII), a partir do onze usamos o cardinal: capítulo doze. 📘"},
{n:"d",t:"Numeral",q:"Compare: (1) 'Comprei um caderno, e não dois.' (2) 'Comprei um caderno lindo.' Em qual frase 'um' é numeral?",a:["Na (1), pois indica a quantidade exata","Na (2), pois indica um caderno qualquer","Nas duas, pois 'um' é sempre numeral","Em nenhuma delas, pois 'um' é sempre artigo"],c:0,e:"Em (1), 'um' se opõe a 'dois': indica quantidade, então é numeral. Em (2), indica um caderno qualquer: é artigo indefinido. 📓"}
];
